package com.icbc.financialinfo.modules.mail;
import com.icbc.financialinfo.modules.review.DepartmentBusinessException;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.support.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.sql.*;import java.util.*;
@Service public class DepartmentMailService{
 private final JdbcTemplate jdbc;public DepartmentMailService(JdbcTemplate j){jdbc=j;}
 public List<RecipientOption> listRecipients(){return jdbc.query("SELECT id,recipient_name,recipient_email FROM mail_recipient ORDER BY id",(r,n)->new RecipientOption(r.getLong(1),r.getString(2),r.getString(3)));}
 public RecipientOption addRecipient(long user,String name,String email){KeyHolder k=new GeneratedKeyHolder();try{jdbc.update(c->{PreparedStatement s=c.prepareStatement("INSERT INTO mail_recipient(recipient_name,recipient_email,created_by,created_at,updated_at) VALUES(?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",Statement.RETURN_GENERATED_KEYS);s.setString(1,name.trim());s.setString(2,email.trim());s.setLong(3,user);return s;},k);}catch(DuplicateKeyException e){throw new DepartmentBusinessException(409,"该收件邮箱已经存在");}return new RecipientOption(k.getKey().longValue(),name.trim(),email.trim());}
 @Transactional public CreateResult create(long manager,CreateRequest q){String status=jdbc.query("SELECT status FROM report WHERE id=?",(r,n)->r.getString(1),q.reportId()).stream().findFirst().orElseThrow(()->new DepartmentBusinessException(404,"报告不存在"));if(!"FINAL_APPROVED".equals(status))throw new DepartmentBusinessException(409,"报告尚未通过终审，不能发送");for(Recipient x:q.recipients()){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM mail_recipient WHERE recipient_name=? AND recipient_email=?",Integer.class,x.name().trim(),x.email().trim());if(n==null||n==0)throw new DepartmentBusinessException(400,"收件人不存在："+x.email());}Integer done=jdbc.queryForObject("SELECT COUNT(*) FROM mail_task WHERE report_id=? AND mail_status IN('SENDING','COMPLETED','SUCCESS')",Integer.class,q.reportId());if(done!=null&&done>0)throw new DepartmentBusinessException(409,"该报告已经发送或正在发送");KeyHolder k=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement s=c.prepareStatement("INSERT INTO mail_task(report_id,subject,mail_body,mail_status,created_by,created_at) VALUES(?,?,?,'PENDING',?,CURRENT_TIMESTAMP)",Statement.RETURN_GENERATED_KEYS);s.setLong(1,q.reportId());s.setString(2,q.subject().trim());s.setString(3,q.mailBody());s.setLong(4,manager);return s;},k);long id=k.getKey().longValue();for(Recipient x:q.recipients())jdbc.update("INSERT INTO mail_log(mail_task_id,recipient_name,recipient_email,mail_status,retry_count,created_at,updated_at) VALUES(?,?,?,'PENDING',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",id,x.name().trim(),x.email().trim());return new CreateResult(id,"PENDING",q.recipients().size());}
 @Transactional public SendResult send(long manager,long id){MailTask t=jdbc.query("SELECT id,report_id,mail_status,created_by FROM mail_task WHERE id=?",(r,n)->new MailTask(r.getLong(1),r.getLong(2),r.getString(3),r.getLong(4)),id).stream().findFirst().orElseThrow(()->new DepartmentBusinessException(404,"邮件任务不存在"));if(t.createdBy()!=manager)throw new DepartmentBusinessException(403,"无权发送其他用户创建的邮件任务");if(!Set.of("PENDING","FAILED","PARTIAL_FAILED").contains(t.status()))throw new DepartmentBusinessException(409,"邮件任务已处理");Integer total=jdbc.queryForObject("SELECT COUNT(*) FROM mail_log WHERE mail_task_id=?",Integer.class,id);if(total==null||total==0)throw new DepartmentBusinessException(409,"邮件任务没有收件人");jdbc.update("UPDATE mail_task SET mail_status='SENDING' WHERE id=?",id);jdbc.update("UPDATE mail_log SET mail_status='SUCCESS',error_message=NULL,provider_message_id=CONCAT('SIMULATED-',id,'-',REPLACE(UUID(),'-','')),sent_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE mail_task_id=?",id);jdbc.update("UPDATE mail_task SET mail_status='COMPLETED',completed_at=CURRENT_TIMESTAMP WHERE id=?",id);jdbc.update("UPDATE report SET status='FINAL_ARCHIVED',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='FINAL_APPROVED'",t.reportId());return new SendResult(id,"COMPLETED",total,total,0);}
 public MailTaskDetail detail(long manager,long id){MailTask t=task(manager,id);return jdbc.query("SELECT id,report_id,subject,mail_body,mail_status,created_by,DATE_FORMAT(created_at,'%Y-%m-%d %H:%i:%s') created_at,DATE_FORMAT(completed_at,'%Y-%m-%d %H:%i:%s') completed_at FROM mail_task WHERE id=?",(r,n)->new MailTaskDetail(r.getLong("id"),r.getLong("report_id"),r.getString("subject"),r.getString("mail_body"),r.getString("mail_status"),r.getLong("created_by"),r.getString("created_at"),r.getString("completed_at")),t.id()).get(0);}
 public List<MailLogDetail> logs(long manager,long id){task(manager,id);return jdbc.query("SELECT id,mail_task_id,recipient_name,recipient_email,mail_status,retry_count,error_message,provider_message_id,DATE_FORMAT(sent_at,'%Y-%m-%d %H:%i:%s') sent_at,DATE_FORMAT(created_at,'%Y-%m-%d %H:%i:%s') created_at,DATE_FORMAT(updated_at,'%Y-%m-%d %H:%i:%s') updated_at FROM mail_log WHERE mail_task_id=? ORDER BY id",(r,n)->new MailLogDetail(r.getLong("id"),r.getLong("mail_task_id"),r.getString("recipient_name"),r.getString("recipient_email"),r.getString("mail_status"),r.getInt("retry_count"),r.getString("error_message"),r.getString("provider_message_id"),r.getString("sent_at"),r.getString("created_at"),r.getString("updated_at")),id);}
 @Transactional public MailLogDetail retry(long manager,long logId){Long taskId=jdbc.query("SELECT mail_task_id FROM mail_log WHERE id=?",(r,n)->r.getLong(1),logId).stream().findFirst().orElseThrow(()->new DepartmentBusinessException(404,"邮件日志不存在"));task(manager,taskId);String status=jdbc.queryForObject("SELECT mail_status FROM mail_log WHERE id=?",String.class,logId);if(!"FAILED".equals(status))throw new DepartmentBusinessException(409,"只有失败记录可以重试");jdbc.update("UPDATE mail_log SET mail_status='SUCCESS',retry_count=retry_count+1,error_message=NULL,provider_message_id=CONCAT('SIMULATED-',id,'-',REPLACE(UUID(),'-','')),sent_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?",logId);return logs(manager,taskId).stream().filter(x->x.id()==logId).findFirst().orElseThrow();}
 private MailTask task(long manager,long id){MailTask t=jdbc.query("SELECT id,report_id,mail_status,created_by FROM mail_task WHERE id=?",(r,n)->new MailTask(r.getLong(1),r.getLong(2),r.getString(3),r.getLong(4)),id).stream().findFirst().orElseThrow(()->new DepartmentBusinessException(404,"邮件任务不存在"));if(t.createdBy()!=manager)throw new DepartmentBusinessException(403,"无权查看其他用户创建的邮件任务");return t;}
 public record CreateRequest(long reportId,String subject,String mailBody,List<Recipient> recipients){} public record Recipient(String name,String email){} public record RecipientOption(long id,String name,String email){} public record CreateResult(long id,String status,int recipientCount){} public record SendResult(long mailTaskId,String status,int totalCount,int successCount,int failedCount){} public record MailTaskDetail(long id,long reportId,String subject,String mailBody,String status,long createdBy,String createdAt,String completedAt){} public record MailLogDetail(long id,long mailTaskId,String recipientName,String recipientEmail,String status,int retryCount,String errorMessage,String providerMessageId,String sentAt,String createdAt,String updatedAt){} private record MailTask(long id,long reportId,String status,long createdBy){}
}
